import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.D64lb950.js";const b=JSON.parse('{"title":"成长思考","description":"","frontmatter":{"title":"成长思考"},"headers":[],"relativePath":"categories/growth-thinking.md","filePath":"categories/growth-thinking.md","lastUpdated":1778083677000}'),i={name:"categories/growth-thinking.md"};function h(s,a,l,n,d,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="🎯-成长思考" tabindex="-1">🎯 成长思考 <a class="header-anchor" href="#🎯-成长思考" aria-label="Permalink to &quot;🎯 成长思考&quot;">​</a></h1><p>关于职业发展、学习方法、效率提升的思考，记录个人成长历程。</p><h2 id="学习规划" tabindex="-1">学习规划 <a class="header-anchor" href="#学习规划" aria-label="Permalink to &quot;学习规划&quot;">​</a></h2><h3 id="我的-2026-年学习计划" tabindex="-1"><a href="/my-blog/posts/2026-learning-plan">我的 2026 年学习计划</a> <a class="header-anchor" href="#我的-2026-年学习计划" aria-label="Permalink to &quot;[我的 2026 年学习计划](/posts/2026-learning-plan)&quot;">​</a></h3><p>新的一年，给自己定下学习目标。技术学习包括 Vue 3 生态深入、TypeScript 类型编程、Vite/Webpack 原理、Nest.js 框架、PostgreSQL/Redis、Docker 容器化、AI 应用开发、Rust 入门。读书计划涵盖技术书籍和非技术书籍。项目实践包括博客系统优化、工具库封装、开源贡献。</p><h2 id="读书笔记" tabindex="-1">读书笔记 <a class="header-anchor" href="#读书笔记" aria-label="Permalink to &quot;读书笔记&quot;">​</a></h2><h3 id="《刻意练习》读书笔记" tabindex="-1"><a href="/my-blog/posts/deliberate-practice-review">《刻意练习》读书笔记</a> <a class="header-anchor" href="#《刻意练习》读书笔记" aria-label="Permalink to &quot;[《刻意练习》读书笔记](/posts/deliberate-practice-review)&quot;">​</a></h3><p>推翻一万小时定律的经典之作。刻意练习的四个标准——明确目标、极度专注、即时反馈、走出舒适区——才是从普通到卓越的真正路径。心理表征理论解释了高手与普通人的本质差异。文章将刻意练习方法应用到编程学习中，提出&quot;目标-反馈-调整&quot;的实战框架。</p><h3 id="《非暴力沟通》读书笔记" tabindex="-1"><a href="/my-blog/posts/nonviolent-communication-review">《非暴力沟通》读书笔记</a> <a class="header-anchor" href="#《非暴力沟通》读书笔记" aria-label="Permalink to &quot;[《非暴力沟通》读书笔记](/posts/nonviolent-communication-review)&quot;">​</a></h3><p>卢森堡博士的全球冲突调解经典。核心四步法——观察而不评判、表达感受而非想法、说出需要而非指责、提出请求而非命令——看似简单，实则需要反复练习。文章包含大量沟通场景的对比实例、技术团队 Code Review 和需求讨论中的应用，以及 30 天沟通日志实践。</p><h3 id="《高效能人士的七个习惯》读书笔记" tabindex="-1"><a href="/my-blog/posts/seven-habits-review">《高效能人士的七个习惯》读书笔记</a> <a class="header-anchor" href="#《高效能人士的七个习惯》读书笔记" aria-label="Permalink to &quot;[《高效能人士的七个习惯》读书笔记](/posts/seven-habits-review)&quot;">​</a></h3><p>柯维把人的成长拆成依赖→独立→互赖三个阶段。七个习惯不是七个独立技巧，是一条完整的成长链。文章逐一深挖每个习惯的核心机制——关注圈与影响圈、以终为始、四象限时间管理、双赢思维、同理心倾听——并给出每日/每周/每月的实践检查体系。</p><h3 id="《思考-快与慢》读书笔记" tabindex="-1"><a href="/my-blog/posts/thinking-fast-and-slow-review">《思考，快与慢》读书笔记</a> <a class="header-anchor" href="#《思考-快与慢》读书笔记" aria-label="Permalink to &quot;[《思考，快与慢》读书笔记](/posts/thinking-fast-and-slow-review)&quot;">​</a></h3><p>诺贝尔经济学奖得主卡尼曼的认知心理学经典。系统1和系统2的运作机制解释了为什么人不是理性的。文章深度解读十几种认知偏差——可得性、锚定、过度自信、损失厌恶、确认偏误等——并将它们映射到编程和技术决策的日常场景中，附决策自检清单。</p><h3 id="《穷查理宝典》读书笔记" tabindex="-1"><a href="/my-blog/posts/poor-charlies-almanack-review">《穷查理宝典》读书笔记</a> <a class="header-anchor" href="#《穷查理宝典》读书笔记" aria-label="Permalink to &quot;[《穷查理宝典》读书笔记](/posts/poor-charlies-almanack-review)&quot;">​</a></h3><p>查理·芒格的智慧合集。核心内容包括多元思维模型、逆向思维、25种人类误判心理学倾向、能力圈概念。文章将芒格的投资检查清单改造为技术决策版，并分析了芒格哲学与七个习惯的内在共鸣。附个人&quot;不可为清单&quot;实践。</p><h3 id="《从0到1》读书笔记" tabindex="-1"><a href="/my-blog/posts/zero-to-one-review">《从0到1》读书笔记</a> <a class="header-anchor" href="#《从0到1》读书笔记" aria-label="Permalink to &quot;[《从0到1》读书笔记](/posts/zero-to-one-review)&quot;">​</a></h3><p>彼得·蒂尔的经典之作，探讨如何创造新事物而非复制已有模式。核心观点：竞争是失败者的游戏，真正有价值的企业必须实现从0到1的跨越。书中详细阐述了垄断的力量、幂次法则、秘密的价值、初创企业的七大问题。这本书改变了我对创业、竞争和未来的看法。</p><h3 id="《穷爸爸富爸爸》读书笔记" tabindex="-1"><a href="/my-blog/posts/rich-dad-poor-dad-review">《穷爸爸富爸爸》读书笔记</a> <a class="header-anchor" href="#《穷爸爸富爸爸》读书笔记" aria-label="Permalink to &quot;[《穷爸爸富爸爸》读书笔记](/posts/rich-dad-poor-dad-review)&quot;">​</a></h3><p>这本书改变了我对金钱和财富的认知方式。核心观点是区分资产与负债：资产能把钱放进你口袋，负债把钱从你口袋拿走。文章详细分析了两个爸爸的不同思维模式、现金流差异、六课核心内容、克服困难的五个障碍，以及我个人的财务自由行动计划。</p><p><strong>核心认知转变：</strong></p><table tabindex="0"><thead><tr><th>旧认知</th><th>新认知</th></tr></thead><tbody><tr><td>高收入 = 富人</td><td>高资产 = 富人</td></tr><tr><td>房子 = 资产</td><td>现金流决定资产属性</td></tr><tr><td>工作稳定 = 安全</td><td>财务自由 = 安全</td></tr><tr><td>风险 = 危险</td><td>风险 = 机会的代价</td></tr></tbody></table><h2 id="随笔" tabindex="-1">随笔 <a class="header-anchor" href="#随笔" aria-label="Permalink to &quot;随笔&quot;">​</a></h2><h3 id="欢迎来到霄鸿臻的博客" tabindex="-1"><a href="/my-blog/posts/hello-world">欢迎来到霄鸿臻的博客</a> <a class="header-anchor" href="#欢迎来到霄鸿臻的博客" aria-label="Permalink to &quot;[欢迎来到霄鸿臻的博客](/posts/hello-world)&quot;">​</a></h3><p>第一篇博客文章，介绍博客的技术选型和功能展示，说明未来将分享技术学习笔记、项目实战经验和个人成长思考。</p><hr><blockquote><p>学习是一个持续的过程，保持好奇心，不断探索新的领域。财商教育是一生的功课，从今天开始行动。</p></blockquote>',27)])])}const u=e(i,[["render",h]]);export{b as __pageData,u as default};
